#!/usr/bin/env bash
# Builds the Flutter example inside a host Android project generated by the
# Flutter on PATH (`flutter create`), so the plugin is checked against the
# Gradle, AGP and Kotlin versions that this Flutter gives a new app.
#
# Use it for the minimum supported Flutter, whose template differs from the
# committed example (that one follows the latest stable template):
#
#   mise x flutter@3.24.5 java@temurin-17 -- scripts/flutter-host-check.sh --lowest
#
# --lowest resolves every dependency to its lowest allowed version
# (`flutter pub downgrade`) to check the lower bounds of the constraints.
set -euo pipefail

LOWEST="false"
if [[ "${1:-}" == "--lowest" ]]; then
  LOWEST="true"
fi

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PLUGIN_DIR="$ROOT_DIR/flutter-plugin"
EXAMPLE_DIR="$PLUGIN_DIR/example"

FLUTTER_VERSION="$(flutter --version --machine | sed -n -E 's/.*"frameworkVersion": *"([^"]+)".*/\1/p')"
[[ -n "$FLUTTER_VERSION" ]] || { echo "could not read the Flutter version" >&2; exit 1; }

WORK_DIR="$ROOT_DIR/build/flutter-host-check/$FLUTTER_VERSION"
APP_DIR="$WORK_DIR/txlnk_adtech_sdk_example"
rm -rf "$WORK_DIR"
mkdir -p "$WORK_DIR"

echo "==> Flutter $FLUTTER_VERSION: new host app from its own template"
(cd "$WORK_DIR" && flutter create --no-pub --platforms=android --org com.txlnk.sdk txlnk_adtech_sdk_example >/dev/null)

grep -h -E 'com.android.application"?\)? version|kotlin.android"?\)? version' \
  "$APP_DIR/android/settings.gradle"* 2>/dev/null | sed 's/^ */    /' || true
grep -h distributionUrl "$APP_DIR/android/gradle/wrapper/gradle-wrapper.properties" | sed 's/^/    /'

rm -rf "${APP_DIR:?}/lib" "${APP_DIR:?}/test"
cp -R "$EXAMPLE_DIR/lib" "$APP_DIR/lib"
cp -R "$EXAMPLE_DIR/test" "$APP_DIR/test"
cp "$EXAMPLE_DIR/analysis_options.yaml" "$APP_DIR/analysis_options.yaml"
sed -E "s#^( *path:) \.\./?\$#\1 $PLUGIN_DIR#" "$EXAMPLE_DIR/pubspec.yaml" > "$APP_DIR/pubspec.yaml"
grep -q "path: $PLUGIN_DIR" "$APP_DIR/pubspec.yaml" || { echo "plugin path not rewritten" >&2; exit 1; }

cd "$APP_DIR"
if [[ "$LOWEST" == "true" ]]; then
  flutter pub downgrade
else
  flutter pub get
fi
flutter analyze
flutter test
flutter build apk --debug
echo "==> OK: Flutter $FLUTTER_VERSION host build"
